  1	/**
  2	 * Tests for session storage configuration in manifest schema
  3	 *
  4	 * AC coverage:
  5	 * - @session-storage-modes ac-config: sessions.storage accepts "local" or "branch"
  6	 * - @session-storage-modes ac-config-default: defaults to "local" when not set
  7	 * - @session-storage-modes ac-config-invalid: Zod validation error for unsupported values
  8	 * - @session-storage-modes ac-branch-name: sessions.branch accepts a string
  9	 * - @session-storage-modes ac-branch-name-default: sessions.branch is optional (defaults handled elsewhere)
 10	 */
 11	
 12	import { describe, it, expect } from "vitest";
 13	import { ManifestSchema } from "../../src/schema/spec.js";
 14	
 15	const baseManifest = {
 16	  kynetic: "1.0",
 17	  project: {
 18	    name: "Test Project",
 19	    version: "1.0.0",
 20	    status: "draft",
 21	  },
 22	};
 23	
 24	describe("Session Storage Config in ManifestSchema", () => {
 25	  // AC: @session-storage-modes ac-config
 26	  it('accepts sessions.storage set to "local"', () => {
 27	    const result = ManifestSchema.safeParse({
 28	      ...baseManifest,
 29	      sessions: { storage: "local" },
 30	    });
 31	
 32	    expect(result.success).toBe(true);
 33	    if (result.success) {
 34	      expect(result.data.sessions?.storage).toBe("local");
 35	    }
 36	  });
 37	
 38	  // AC: @session-storage-modes ac-config
 39	  it('accepts sessions.storage set to "branch"', () => {
 40	    const result = ManifestSchema.safeParse({
 41	      ...baseManifest,
 42	      sessions: { storage: "branch" },
 43	    });
 44	
 45	    expect(result.success).toBe(true);
 46	    if (result.success) {
 47	      expect(result.data.sessions?.storage).toBe("branch");
 48	    }
 49	  });
 50	
 51	  // AC: @session-storage-modes ac-config-default
 52	  it("defaults storage to 'local' when sessions block is present without storage", () => {
 53	    const result = ManifestSchema.safeParse({
 54	      ...baseManifest,
 55	      sessions: {},
 56	    });
 57	
 58	    expect(result.success).toBe(true);
 59	    if (result.success) {
 60	      expect(result.data.sessions?.storage).toBe("local");
 61	    }
 62	  });
 63	
 64	  // AC: @session-storage-modes ac-config-default
 65	  it("defaults sessions.storage to 'local' when sessions block is omitted", () => {
 66	    const result = ManifestSchema.safeParse(baseManifest);
 67	
 68	    expect(result.success).toBe(true);
 69	    if (result.success) {
 70	      expect(result.data.sessions).toEqual({ storage: "local" });
 71	    }
 72	  });
 73	
 74	  // AC: @session-storage-modes ac-config-invalid
 75	  it("rejects unsupported sessions.storage value", () => {
 76	    const result = ManifestSchema.safeParse({
 77	      ...baseManifest,
 78	      sessions: { storage: "remote" },
 79	    });
 80	
 81	    expect(result.success).toBe(false);
 82	    if (!result.success) {
 83	      const storageError = result.error.issues.find(
 84	        (issue) => issue.path.includes("storage")
 85	      );
 86	      expect(storageError).toBeDefined();
 87	      expect(storageError!.message).toContain("Invalid enum value");
 88	      expect(storageError!.message).toContain("local");
 89	      expect(storageError!.message).toContain("branch");
 90	    }
 91	  });
 92	
 93	  // AC: @session-storage-modes ac-config-invalid
 94	  it("rejects invalid type for sessions.storage", () => {
 95	    const result = ManifestSchema.safeParse({
 96	      ...baseManifest,
 97	      sessions: { storage: 42 },
 98	    });
 99	
100	    expect(result.success).toBe(false);
101	  });
102	
103	  // AC: @session-storage-modes ac-branch-name
104	  it("accepts sessions.branch as a string", () => {
105	    const result = ManifestSchema.safeParse({
106	      ...baseManifest,
107	      sessions: { storage: "branch", branch: "kspec-sessions" },
108	    });
109	
110	    expect(result.success).toBe(true);
111	    if (result.success) {
112	      expect(result.data.sessions?.branch).toBe("kspec-sessions");
113	    }
114	  });
115	
116	  // AC: @session-storage-modes ac-branch-name-default
117	  it("allows sessions.branch to be omitted", () => {
118	    const result = ManifestSchema.safeParse({
119	      ...baseManifest,
120	      sessions: { storage: "branch" },
121	    });
122	
123	    expect(result.success).toBe(true);
124	    if (result.success) {
125	      expect(result.data.sessions?.branch).toBeUndefined();
126	    }
127	  });
128	
129	  it("works alongside other manifest fields", () => {
130	    const result = ManifestSchema.safeParse({
131	      ...baseManifest,
132	      sessions: { storage: "branch", branch: "my-sessions" },
133	      includes: ["modules/main.yaml"],
134	      hooks: { "pre-commit": "npm test" },
135	    });
136	
137	    expect(result.success).toBe(true);
138	    if (result.success) {
139	      expect(result.data.sessions?.storage).toBe("branch");
140	      expect(result.data.sessions?.branch).toBe("my-sessions");
141	      expect(result.data.includes).toEqual(["modules/main.yaml"]);
142	    }
143	  });
144	});

